const {getDatabase}=require('../_db');
const {authenticatedUser}=require('./_auth');
module.exports=async function handler(request,response){
  if(request.method!=='GET')return response.status(405).json({error:'Método não permitido'});
  const user=await authenticatedUser(request);if(!user)return response.status(401).json({error:'Sessão expirada.'});
  try{
    const status=String(request.query?.status||'').trim(),includeSummary=String(request.query?.summary??'1')!=='0',sql=getDatabase();let rows;
    if(status==='__NAO_RESPONDIDAS__')rows=await sql`SELECT a.id,a.numero_atendimento,a.nome_cliente,a.telefone,a.status,a.montador_id,a.atendente_id,u.nome_exibicao AS atendente_nome,a.detalhes_servico,a.agendado_para,a.valor_servico,a.criado_em,a.atualizado_em,l.tipo_remetente AS ultimo_tipo_remetente,l.criado_em AS ultima_mensagem_em FROM atendimentos a LEFT JOIN usuarios_atendimento u ON u.id=a.atendente_id LEFT JOIN LATERAL (SELECT tipo_remetente,criado_em FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE WHERE l.tipo_remetente='CLIENTE' AND a.status NOT IN ('SERVICO_FINALIZADO','CANCELADO') ORDER BY a.atualizado_em DESC LIMIT 100`;
    else if(status)rows=await sql`SELECT a.id,a.numero_atendimento,a.nome_cliente,a.telefone,a.status,a.montador_id,a.atendente_id,u.nome_exibicao AS atendente_nome,a.detalhes_servico,a.agendado_para,a.valor_servico,a.criado_em,a.atualizado_em,l.tipo_remetente AS ultimo_tipo_remetente,l.criado_em AS ultima_mensagem_em FROM atendimentos a LEFT JOIN usuarios_atendimento u ON u.id=a.atendente_id LEFT JOIN LATERAL (SELECT tipo_remetente,criado_em FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE WHERE a.status=${status} ORDER BY (l.tipo_remetente='CLIENTE') DESC,(a.atendente_id IS NULL) DESC,a.atualizado_em DESC LIMIT 100`;
    else rows=await sql`SELECT a.id,a.numero_atendimento,a.nome_cliente,a.telefone,a.status,a.montador_id,a.atendente_id,u.nome_exibicao AS atendente_nome,a.detalhes_servico,a.agendado_para,a.valor_servico,a.criado_em,a.atualizado_em,l.tipo_remetente AS ultimo_tipo_remetente,l.criado_em AS ultima_mensagem_em FROM atendimentos a LEFT JOIN usuarios_atendimento u ON u.id=a.atendente_id LEFT JOIN LATERAL (SELECT tipo_remetente,criado_em FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE WHERE a.status NOT IN ('SERVICO_FINALIZADO','CANCELADO') ORDER BY (l.tipo_remetente='CLIENTE') DESC,(a.atendente_id IS NULL) DESC,a.atualizado_em DESC LIMIT 100`;
    let contagens=[],naoRespondidas=[];
    if(includeSummary)[contagens,naoRespondidas]=await Promise.all([sql`SELECT status,COUNT(*)::int AS quantidade FROM atendimentos GROUP BY status`,sql`SELECT COUNT(*)::int AS quantidade FROM atendimentos a LEFT JOIN LATERAL (SELECT tipo_remetente FROM mensagens WHERE atendimento_id=a.id ORDER BY criado_em DESC LIMIT 1) l ON TRUE WHERE l.tipo_remetente='CLIENTE' AND a.status NOT IN ('SERVICO_FINALIZADO','CANCELADO')`]);
    return response.status(200).json({atendimentos:rows,contagens,naoRespondidas:naoRespondidas[0]?.quantidade||0,usuario:{id:user.id,nomeExibicao:user.nome_exibicao,login:user.login,perfil:user.perfil}});
  }catch(error){console.error(error);return response.status(500).json({error:'Não foi possível carregar os atendimentos.'})}
};
